Etwas ganz anderes: Portiere diese alte Delphi-Unit idiomatisch nach Go, mit Fehlerwerten statt Exceptions und einem Callback statt des Events. Was ist bei History zu beachten?

```pascal
unit MovingAverage;

{$mode delphi}

interface

uses
  SysUtils, Generics.Collections;

type
  EMovingAverage = class(Exception);

  TMovingAverage = class
  private
    FWindow: Integer;
    FBuffer: array of Double;
    FHead: Integer;
    FCount: Integer;
    FSum: Double;
    FOnFull: TNotifyEvent;
    function GetValue: Double;
    function GetFull: Boolean;
  public
    constructor Create(AWindow: Integer);
    procedure Add(const AValue: Double);
    procedure AddRange(const AValues: array of Double);
    procedure Reset;
    function History: TList<Double>;
    property Value: Double read GetValue;
    property Full: Boolean read GetFull;
    property Window: Integer read FWindow;
    property OnFull: TNotifyEvent read FOnFull write FOnFull;
  end;

implementation

constructor TMovingAverage.Create(AWindow: Integer);
begin
  inherited Create;
  if AWindow < 1 then
    raise EMovingAverage.CreateFmt('Fensterbreite muss >= 1 sein, nicht %d', [AWindow]);
  FWindow := AWindow;
  SetLength(FBuffer, AWindow);
  Reset;
end;

procedure TMovingAverage.Add(const AValue: Double);
var
  WasFull: Boolean;
begin
  WasFull := Full;
  if Full then
    FSum := FSum - FBuffer[FHead]
  else
    Inc(FCount);
  FBuffer[FHead] := AValue;
  FSum := FSum + AValue;
  FHead := (FHead + 1) mod FWindow;
  if (not WasFull) and Full and Assigned(FOnFull) then
    FOnFull(Self);
end;

procedure TMovingAverage.AddRange(const AValues: array of Double);
var
  V: Double;
begin
  for V in AValues do
    Add(V);
end;

procedure TMovingAverage.Reset;
begin
  FHead := 0;
  FCount := 0;
  FSum := 0;
  FillChar(FBuffer[0], Length(FBuffer) * SizeOf(Double), 0);
end;

function TMovingAverage.GetValue: Double;
begin
  if FCount = 0 then
    raise EMovingAverage.Create('Noch keine Werte');
  Result := FSum / FCount;
end;

function TMovingAverage.GetFull: Boolean;
begin
  Result := FCount = FWindow;
end;

function TMovingAverage.History: TList<Double>;
var
  I, Start: Integer;
begin
  Result := TList<Double>.Create;
  try
    Start := (FHead - FCount + FWindow) mod FWindow;
    for I := 0 to FCount - 1 do
      Result.Add(FBuffer[(Start + I) mod FWindow]);
  except
    Result.Free;
    raise;
  end;
end;

end.
```

