	if window < 1 {
		return nil, ErrWindowTooSmall
	}
	return &MovingAverage{
		window: window,
		buffer: make([]float64, window),
	}, nil
}

// Add fügt einen einzelnen Wert hinzu.
func (m *MovingAverage) Add(value float64) {
	wasFull := m.count == m.window

