```vhdl
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity fir16 is
  generic (
    COEFFS : integer_vector(0 to 15) := (others => 0)
  );
  port (
    clk   : in  std_logic;
    rst   : in  std_logic;
    valid : in  std_logic;
    x     : in  signed(15 downto 0);
    y     : out signed(15 downto 0);
    y_vld : out std_logic
  );
end entity;

architecture rtl of fir16 is
  type taps_t is array (0 to 15) of signed(15 downto 0);
  signal taps : taps_t := (others => (others => '0'));
  signal acc  : signed(35 downto 0);
begin
  process (clk)
    variable sum : signed(35 downto 0);
  begin
    if rising_edge(clk) then
      if rst = '1' then
        taps  <= (others => (others => '0'));
        y_vld <= '0';
      elsif valid = '1' then
        taps <= x & taps(0 to 14);
        sum := (others => '0');
        for i in 0 to 15 loop
          sum := sum + taps(i) * to_signed(COEFFS(i), 16);
        end loop;
        acc   <= sum;
        y     <= acc(30 downto 15);
        y_vld <= '1';
      end if;
    end if;
  end process;
end architecture;
